import React, { useEffect, useState } from 'react';

function FeedbackList({ reloadFlag }) {
  const [feedbacks, setFeedbacks] = useState([]);

  useEffect(() => {
    fetch('http://localhost:3001/api/feedback')
      .then(res => res.json())
      .then(data => setFeedbacks(data));
  }, [reloadFlag]);

  return (
    <div style={{ marginTop: '2rem' }}>
      <h3>Отзывы пользователей</h3>
      {feedbacks.length === 0 && <p>Пока нет отзывов.</p>}
      {feedbacks.map(fb => (
        <div key={fb.id} style={{ borderBottom: '1px solid #ccc', marginBottom: '1rem' }}>
          <p><strong>{fb.username}</strong> ({new Date(fb.submitted_at).toLocaleString()}):</p>
          <p>{fb.comment}</p>
        </div>
      ))}
    </div>
  );
}

export default FeedbackList;
